CREATE FUNCTION set_updated_at_now() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN NEW.updated_at := CURRENT_TIMESTAMP; RETURN NEW; END $$;
CREATE TRIGGER "trg_sales_channel_api_context_updated_at_on_update" BEFORE UPDATE ON "sales_channel_api_context" FOR EACH ROW EXECUTE FUNCTION set_updated_at_now();
